from app.db import query
def stats():return {'active_incidents':query("SELECT COUNT(*) c FROM incidents WHERE status IN ('PENDING','ASSIGNED','UNDER_REVIEW')",one=True)['c'],'pending_review':query("SELECT COUNT(*) c FROM incidents WHERE status='PENDING'",one=True)['c'],'confirmed_today':query("SELECT COUNT(*) c FROM incidents WHERE status='CONFIRMED' AND DATE(reviewed_at)=CURDATE()",one=True)['c'],'active_officers':query("SELECT COUNT(*) c FROM users WHERE role IN ('NGO_OFFICER','GOV_OFFICER') AND status='active'",one=True)['c'],'active_sos':query("SELECT COUNT(*) c FROM sos_alerts WHERE status IN ('ACTIVE','ACKNOWLEDGED')",one=True)['c']}
def score():
 r=query("SELECT SUM(severity='critical') c1,SUM(severity='high') c2,SUM(severity='medium') c3,SUM(severity='low') c4 FROM incidents WHERE status IN ('CONFIRMED','RESOLVED') AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)",one=True); risk=(r['c1'] or 0)*10+(r['c2'] or 0)*6+(r['c3'] or 0)*3+(r['c4'] or 0);return max(0,min(100,100-risk))
